+// UniFFI supplies a poll/free pair for each async FFI result type. Resolve
+// those stable ABI symbols once and verify their shapes, so ownership works
+// for generated wrappers in both normal and verbose modes without JS hooks.
+void identifyFutureFunctions(std::vector<FnInfo> &fns) {
+  const std::string pollMarker = "_rust_future_poll_";
+  for (auto &poll : fns) {
+    const auto marker = poll.name.find(pollMarker);
+    if (poll.name.rfind("ffi_", 0) != 0 || marker == std::string::npos ||
+        poll.args.size() != 3 || poll.args[0].tag != UBRN_TY_HANDLE ||
+        poll.args[1].tag != UBRN_TY_CALLBACK ||
+        poll.args[1].name != "RustFutureContinuationCallback" ||
+        poll.args[2].tag != UBRN_TY_HANDLE || poll.retTag != UBRN_TY_VOID ||
+        poll.hasRcs) {
+      continue;
+    }
+    auto freeName = poll.name;
+    freeName.replace(marker, pollMarker.size(), "_rust_future_free_");
+    for (auto &free : fns) {
+      if (free.name == freeName && free.args.size() == 1 &&
+          free.args[0].tag == UBRN_TY_HANDLE && free.retTag == UBRN_TY_VOID &&
+          !free.hasRcs) {
+        poll.futureFree = free.name;
+        free.isFutureFree = true;
+        break;
+      }
+    }
+  }
