+    const void *args[] = {&future};
+    const size_t sizes[] = {sizeof(future)};
+    // Still armed here: root teardown aborts every callback first, frees
+    // futures second, and only then disarms the module's native call path.
+    ubrn_jsi_call(info.module, freeName.c_str(), args, sizes, 1, nullptr, nullptr,
+                  0);
+  }
