+// One registration is one owned Arc reference, even when several wrappers
+// contain the same pointer. Entries, rather than JS finalizers, own cleanup.
+class RustObjectRegistry : public std::enable_shared_from_this<RustObjectRegistry> {
+  struct Entry {
+    uint64_t pointer;
+    std::string freeName;
+  };
+
+public:
+  RustObjectRegistry(UbrnJsiModule *module,
+                     std::shared_ptr<facebook::react::CallInvoker> invoker,
+                     std::weak_ptr<void> root)
+      : module_(module), invoker_(std::move(invoker)), root_(std::move(root)) {}
+
+  uint64_t add(uint64_t pointer, std::string freeName) {
+    std::lock_guard<std::mutex> lock(mutex_);
+    if (closed_) {
+      throw std::logic_error("uniffi jsi player: object registry is closed");
+    }
+    const auto id = ++nextId_;
+    entries_.emplace(id, Entry{pointer, std::move(freeName)});
+    return id;
+  }
+
+  // Called after generated JS explicitly consumed the Arc. The guard may be
+  // finalized much later, including after the module was disarmed.
+  void forget(uint64_t id) {
+    std::lock_guard<std::mutex> lock(mutex_);
+    entries_.erase(id);
+  }
+
+  // A HostObject finalizer can run inside GC on any thread. It must not call
+  // Rust (whose Drop could call JS) there. Queue ordinary collection instead;
+  // root teardown drains anything whose queued callback is discarded.
+  void abandon(uint64_t id) {
+    {
+      std::lock_guard<std::mutex> lock(mutex_);
+      if (closed_ || entries_.find(id) == entries_.end()) {
+        return;
+      }
+    }
+    std::weak_ptr<RustObjectRegistry> weak = shared_from_this();
+    invoker_->invokeAsync([weak, id]() {
+      if (auto registry = weak.lock()) {
+        registry->release(id);
+      }
+    });
+  }
+
+  // Only the JS thread or a host with a stopped/joined JS queue may release
+  // native ownership. The conservative off-thread path still closes the
+  // registry so later finalizers cannot call a disarmed module.
+  void close(bool releaseNative) {
+    std::map<uint64_t, Entry> entries;
+    {
+      std::lock_guard<std::mutex> lock(mutex_);
+      if (closed_) {
+        return;
+      }
+      closed_ = true;
+      entries.swap(entries_);
+    }
+    if (releaseNative) {
+      for (const auto &[id, entry] : entries) {
+        free(entry);
+      }
+    }
+  }
+
+private:
+  void release(uint64_t id) {
+    // Pin the player only while this queued callback executes, never while it
+    // sits in the invoker. Otherwise a dead queue could retain its own root.
+    const auto root = root_.lock();
+    if (!root) {
+      return;
+    }
+    Entry entry;
+    {
+      std::lock_guard<std::mutex> lock(mutex_);
+      const auto found = entries_.find(id);
+      if (found == entries_.end()) {
+        return;
+      }
+      entry = std::move(found->second);
+      entries_.erase(found);
+    }
+    // Queue-safe close cannot race this JS-thread native call. Do not hold
+    // the registry lock over Rust, whose destructor can call back into JS.
+    free(entry);
+  }
+
+  void free(const Entry &entry) {
+    const void *args[] = {&entry.pointer};
+    const size_t sizes[] = {sizeof(entry.pointer)};
+    RustCallStatus status{};
+    ubrn_jsi_call(module_, entry.freeName.c_str(), args, sizes, 1, &status,
+                  nullptr, 0);
+    // A native Drop panic has already consumed the Arc. Destructors cannot
+    // throw into JS, but its panic buffer must still be released.
+    if (status.error_buf.data != nullptr) {
+      ubrn_jsi_rustbuffer_free(module_, status.error_buf);
+    }
+  }
+
+  UbrnJsiModule *module_;
+  std::shared_ptr<facebook::react::CallInvoker> invoker_;
+  std::weak_ptr<void> root_;
+  std::mutex mutex_;
+  uint64_t nextId_ = 0;
+  bool closed_ = false;
+  std::map<uint64_t, Entry> entries_;
+};
