+class RustObjectGuard : public jsi::HostObject {
+public:
+  RustObjectGuard(std::shared_ptr<RustObjectRegistry> registry, uint64_t id)
+      : registry_(std::move(registry)), id_(id) {}
+
+  ~RustObjectGuard() override {
+    try {
+      registry_->abandon(id_);
+    } catch (...) {
+      // A stopped invoker can reject scheduling. The root still owns the
+      // registration and releases it at its queue-safe teardown boundary.
+    }
+  }
